def encode_agg3(subcalls):
    n = len(subcalls)
    head_words = [hex(32)[2:].rjust(64, "0"), hex(n)[2:].rjust(64, "0")]
    tuple_offsets, tuple_bodies = [], []
    cur_offset = 32 * n
    for target, cd_hex in subcalls:
        cd_clean = cd_hex[2:] if cd_hex.startswith("0x") else cd_hex
        cd_bytes_len = len(cd_clean) // 2
        padded_cd = cd_clean + ("0" * ((64 - (len(cd_clean) % 64)) % 64))
        body = (
            target.lower().replace("0x", "").rjust(64, "0")
            + ("1").rjust(64, "0")
            + hex(96)[2:].rjust(64, "0")
            + hex(cd_bytes_len)[2:].rjust(64, "0")
            + padded_cd
        )
        tuple_offsets.append(hex(cur_offset)[2:].rjust(64, "0"))
        tuple_bodies.append(body)
        cur_offset += len(body) // 2
    return "0x82ad56cb" + "".join(head_words + tuple_offsets + tuple_bodies)


def decode_agg3(ret_hex, count):
    if not isinstance(ret_hex, str) or len(ret_hex) < 66:
        return [(False, b"")] * count
    raw = bytes.fromhex(ret_hex[2:] if ret_hex.startswith("0x") else ret_hex)
    if len(raw) < 64:
        return [(False, b"")] * count
    arr_off = int.from_bytes(raw[0:32], "big")
    n = int.from_bytes(raw[arr_off : arr_off + 32], "big")
    base = arr_off + 32
    out = []
    for i in range(min(n, count)):
        elem_off = base + int.from_bytes(raw[base + i * 32 : base + (i + 1) * 32], "big")
        success = int.from_bytes(raw[elem_off : elem_off + 32], "big") == 1
        data_off = elem_off + int.from_bytes(raw[elem_off + 32 : elem_off + 64], "big")
        data_len = int.from_bytes(raw[data_off : data_off + 32], "big")
        data_bytes = raw[data_off + 32 : data_off + 32 + data_len]
        out.append((success, data_bytes))
    return out


def mc3_call(subcalls, from_addr=None, rpc_hint=0):
    if not subcalls:
        return []
    cd = encode_agg3(subcalls)
    call_obj = {"to": MC3, "data": cd}
    if from_addr:
        call_obj["from"] = from_addr
    payload = {"jsonrpc": "2.0", "id": 1, "method": "eth_call", "params": [call_obj, "latest"]}
    for attempt in range(len(RPCS)):
        u = RPCS[(rpc_hint + attempt) % len(RPCS)]
        try:
            r = urllib.request.Request(
                u,
                data=json.dumps(payload).encode(),
                headers={"Content-Type": "application/json", "User-Agent": "Mozilla/5.0"},
            )
            parsed = json.loads(urllib.request.urlopen(r, timeout=5).read().decode())
            if isinstance(parsed, dict) and parsed.get("result"):
                dec = decode_agg3(parsed["result"], len(subcalls))
                if dec and any(ok_x for ok_x, _ in dec):
                    return dec
        except Exception:
            continue
    return [(False, b"")] * len(subcalls)


_CACHED_LIQ = {"ts": 0.0, "res": []}
_CACHED_MC3_CODE = None


def encode_fs(pb, ps, tb, tq, amt, mg, z0, z1, rf):
    words = [
        pb.lower().replace("0x", "").rjust(64, "0"),
        ps.lower().replace("0x", "").rjust(64, "0"),
        tb.lower().replace("0x", "").rjust(64, "0"),
        tq.lower().replace("0x", "").rjust(64, "0"),
        hex(int(amt))[2:].rjust(64, "0"),
        hex(int(mg))[2:].rjust(64, "0"),
        ("1" if z0 else "0").rjust(64, "0"),
        ("1" if z1 else "0").rjust(64, "0"),
        hex(int(rf))[2:].rjust(64, "0"),
    ]
    return "0x3260f1cc" + "".join(words)


def main(quiet=False):
    global _CACHED_MC3_CODE
    t0_start = time.time()
    REPORTS.mkdir(parents=True, exist_ok=True)
    s0_subs = []
    liq_subs = []
    for _, p_addr, dex_t, _, _, _, _, _ in POOLS:
        sig = "0xe76c01e4" if dex_t == "ALG" else "0x3850c7bd"
        s0_subs.append((p_addr, sig))
        liq_subs.append((p_addr, "0x1a686502"))

    mid_q = len(POOLS) // 2
    need_liq_refresh = (t0_start - float(_CACHED_LIQ.get("ts", 0.0))) >= 15.0 or len(_CACHED_LIQ.get("res", [])) != len(POOLS)
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as ex:
        f_s0 = [
            ex.submit(mc3_call, s0_subs[:mid_q], None, 0),
            ex.submit(mc3_call, s0_subs[mid_q:], None, 1),
        ]
        if need_liq_refresh:
            f_lq = [
                ex.submit(mc3_call, liq_subs[:mid_q], None, 2),
                ex.submit(mc3_call, liq_subs[mid_q:], None, 3),
            ]
            liq_res = f_lq[0].result() + f_lq[1].result()
            if sum(1 for ok_l, _ in liq_res if ok_l) >= int(len(POOLS) * 0.92):
                _CACHED_LIQ["ts"] = t0_start
                _CACHED_LIQ["res"] = liq_res
            elif len(_CACHED_LIQ.get("res", [])) == len(POOLS):
                liq_res = _CACHED_LIQ["res"]
        else:
            liq_res = _CACHED_LIQ["res"]
        s0_res = f_s0[0].result() + f_s0[1].result()

    by_pair = {}
    for idx, (pkey, p_addr, dex_t, fee_bps, t0, t1, d0, d1) in enumerate(POOLS):
        ok_s, b_s = s0_res[idx] if idx < len(s0_res) else (False, b"")
        ok_l, b_l = liq_res[idx] if idx < len(liq_res) else (False, b"")
        if not ok_s or not ok_l or len(b_s) < 32 or len(b_l) < 32:
            continue
        sqrt_p = int.from_bytes(b_s[0:32], "big") / float(1 << 96)
        liq = float(int.from_bytes(b_l[0:32], "big"))
        if sqrt_p <= 0 or liq <= 0:
            continue
        live_fee_bps = float(fee_bps)
        if dex_t == "ALG" and len(b_s) >= 96:
            alg_f = int.from_bytes(b_s[64:96], "big")
            if 0 < alg_f <= 50000:
                live_fee_bps = alg_f / 100.0
        raw_p = sqrt_p * sqrt_p
        price_t1_per_t0 = raw_p * (10 ** (d0 - d1))
        r0 = (liq / sqrt_p) / (10 ** d0)
        r1 = (liq * sqrt_p) / (10 ** d1)
        by_pair.setdefault(pkey, []).append({
            "pool": p_addr,
            "dex_t": dex_t,
            "fee_bps": live_fee_bps,
            "price": price_t1_per_t0,
            "r0": r0,
            "r1": r1,
            "t0": t0,
            "t1": t1,
            "d0": d0,
            "d1": d1,
        })

    weth_usdc_pools = by_pair.get("WETH_USDC", [])
    univ3_eth_spot = weth_usdc_pools[0]["price"] if weth_usdc_pools else 2340.0
    pref_order = [
        WETH.lower(), USDC.lower(), USDT.lower(), USDCE.lower(), DAI.lower(), LUSD.lower(),
        USDE.lower(), FRAX.lower(), WBTC.lower(), WSTETH.lower(), WEETH.lower(), CBETH.lower(),
        EZETH.lower(), RSETH.lower(), ARB.lower(), LINK.lower(), UNI.lower(), AAVE.lower(),
        PENDLE.lower(), GMX.lower(), MAGIC.lower(), RDNT.lower(), PEPE.lower(), CRV.lower(),
        GRAIL.lower(), ZRO.lower(), CAKE.lower(), ANIME.lower(), LDO.lower(), STG.lower(),
        SYN.lower(), GNS.lower(), JOE.lower(), COMP.lower(), BAL.lower(), GRT.lower(),
        RPL.lower(), FXS.lower(), SPA.lower(), XAI.lower(), BOOP.lower(), AIDOGE.lower(),
    ]
    tok_usd_map = {
        WETH.lower(): univ3_eth_spot,
        WSTETH.lower(): univ3_eth_spot * 1.18,
        WEETH.lower(): univ3_eth_spot * 1.05,
        CBETH.lower(): univ3_eth_spot * 1.08,
        EZETH.lower(): univ3_eth_spot * 1.03,
        RSETH.lower(): univ3_eth_spot * 1.03,
        WBTC.lower(): 68000.0,
        GRAIL.lower(): 850.0,
        AAVE.lower(): 150.0,
        COMP.lower(): 48.0,
        GMX.lower(): 22.0,
        LINK.lower(): 14.0,
        RPL.lower(): 10.5,
        UNI.lower(): 7.5,
        PENDLE.lower(): 4.2,
        ZRO.lower(): 3.5,
        CAKE.lower(): 2.1,
        FXS.lower(): 1.85,
        BAL.lower(): 1.80,
        GNS.lower(): 1.75,
        LDO.lower(): 1.2,
        DAI.lower(): 1.0,
        LUSD.lower(): 1.0,
        USDC.lower(): 1.0,
        USDT.lower(): 1.0,
        USDCE.lower(): 1.0,
        USDE.lower(): 1.0,
        FRAX.lower(): 1.0,
        ARB.lower(): 0.55,
        SYN.lower(): 0.42,
        JOE.lower(): 0.38,
        CRV.lower(): 0.35,
        MAGIC.lower(): 0.35,
        STG.lower(): 0.32,
        XAI.lower(): 0.18,
        GRT.lower(): 0.15,
        RDNT.lower(): 0.05,
        ANIME.lower(): 0.03,
        SPA.lower(): 0.015,
        BOOP.lower(): 0.00015,
        PEPE.lower(): 0.00001,
        AIDOGE.lower(): 0.0000000002,
    }

    solved_probes = []
    for pkey, plist in by_pair.items():
        n = len(plist)
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                p_buy = plist[i]
                p_sell = plist[j]
                if p_buy["price"] <= 0 or p_sell["price"] <= 0:
                    continue
                spread_bps = ((p_sell["price"] - p_buy["price"]) / p_buy["price"]) * 10000.0
                fee_sum = p_buy["fee_bps"] + p_sell["fee_bps"]
                edge_bps = spread_bps - fee_sum
                if edge_bps < -5.5 or spread_bps > 4000.0:
                    continue
                is_fixed_v3 = (p_buy.get("dex_t") == "V3" and p_sell.get("dex_t") == "V3")
                eff_edge = min(600.0, max(3.5, edge_bps)) * 1e-4

                t0_l = p_buy["t0"].lower()
                t1_l = p_buy["t1"].lower()
                idx0 = pref_order.index(t0_l) if t0_l in pref_order else 99
                idx1 = pref_order.index(t1_l) if t1_l in pref_order else 99
                borrow_is_t0 = idx0 <= idx1

                if borrow_is_t0:
                    r_a, r_b = p_sell["r0"], p_buy["r0"]
                    borrow_tok, target_tok = p_buy["t0"], p_buy["t1"]
                    dec_b = p_buy["d0"]
                    z0, z1 = True, False
                    pb_addr, ps_addr = p_sell["pool"], p_buy["pool"]
                else:
                    r_a, r_b = p_buy["r1"], p_sell["r1"]
                    borrow_tok, target_tok = p_buy["t1"], p_buy["t0"]
                    dec_b = p_buy["d1"]
                    z0, z1 = False, True
                    pb_addr, ps_addr = p_buy["pool"], p_sell["pool"]

                if (r_a + r_b) <= 0:
                    continue
                bt_low = borrow_tok.lower()
                tok_usd = tok_usd_map.get(bt_low, 0.55)
                if bt_low in (WETH.lower(), WSTETH.lower(), WEETH.lower(), CBETH.lower(), EZETH.lower(), RSETH.lower()):
                    min_human, max_human, min_res = 0.00002, 1.25, 0.0002
                elif dec_b == 6:
                    min_human, max_human, min_res = 0.05, 2500.0, 0.50
                elif dec_b == 8:
                    min_human, max_human, min_res = 0.000002, 0.05, 0.00001
                elif bt_low in (AAVE.lower(), COMP.lower()):
                    min_human, max_human, min_res = 0.001, 15.0, 0.005
                elif bt_low in (LINK.lower(), UNI.lower(), PENDLE.lower(), GMX.lower(), RPL.lower()):
                    min_human, max_human, min_res = 0.01, 250.0, 0.05
                else:
                    min_human, max_human, min_res = 0.05, 2500.0, 0.50

                # Exclude dead/dust pools whose virtual active-tick reserve is below $0.25 USD
                if r_a < min_res or r_b < min_res or (min(r_a, r_b) * tok_usd < 0.25):
                    continue

                d_star_human = 0.5 * eff_edge * (r_a * r_b) / (r_a + r_b)
                d_star_clamped = max(min_human, min(max_human, d_star_human))
                raw_amt = max(1, int(d_star_clamped * (10 ** dec_b)))
                raw_035x = max(1, int(raw_amt * 0.35))
                raw_05x = max(1, int(raw_amt * 0.50))
                raw_070x = max(1, int(raw_amt * 0.70))
                raw_150x = max(2, int(min(max_human * 1.50, d_star_clamped * 1.50) * (10 ** dec_b)))
                raw_175x = max(2, int(min(max_human * 1.75, d_star_clamped * 1.75) * (10 ** dec_b)))
                raw_225x = max(2, int(min(max_human * 2.25, d_star_clamped * 2.25) * (10 ** dec_b)))

                # Rank by theoretical Lagrangian gross profit in wei (combining edge_bps AND pool depth d*)
                if edge_bps > 0:
                    est_prof_human = 0.5 * (min(edge_bps, 900.0) * 1e-4) * d_star_clamped
                else:
                    est_prof_human = 0.15 * (max(0.2, 6.0 + edge_bps) * 1e-4) * d_star_clamped
                est_gross_wei = int(est_prof_human * (tok_usd / max(500.0, univ3_eth_spot)) * 1e18)

                solved_probes.append({
                    "label": f"DSTAR_{pkey}_{i}_{j}",
                    "pool_borrow": pb_addr,
                    "pool_sell": ps_addr,
                    "borrow_token": borrow_tok,
                    "target_token": target_tok,
                    "borrow_dec": dec_b,
                    "d_star_raw": raw_amt,
                    "d_star_tiers_raw": [raw_05x, raw_amt, raw_175x],
                    "d_star_5point_grid_raw": [raw_035x, raw_070x, raw_amt, raw_150x, raw_225x],
                    "zero_for_one_borrow": z0,
                    "zero_for_one_sell": z1,
                    "is_fixed_fee_low_gas": is_fixed_v3,
                    "live_spread_bps": round(spread_bps, 3),
                    "fee_floor_bps": round(fee_sum, 2),
                    "live_edge_bps": round(edge_bps, 3),
                    "est_gross_wei": est_gross_wei,
                    "live_verified_gross_wei": 0,
                })

    # Solve 3-Hop Triangular Arbitrage Cycles across WETH <-> {USDC, USDT, USDCE} <-> {ARB, WBTC, DAI, LINK, UNI, AAVE, PENDLE, WSTETH, LUSD}
    triangular_cycles = []
    tri_legs = [
        ("ARB", ARB, "WETH_ARB", False, [("USDC", USDC, "ARB_USDC", False), ("USDT", USDT, "ARB_USDT", False), ("USDCE", USDCE, "ARB_USDCE", False)]),
        ("WBTC", WBTC, "WBTC_WETH", True, [("USDC", USDC, "WBTC_USDC", False), ("USDT", USDT, "WBTC_USDT", False), ("USDCE", USDCE, "WBTC_USDCE", False)]),
        ("DAI", DAI, "WETH_DAI", False, [("USDC", USDC, "USDC_DAI", True), ("USDT", USDT, "DAI_USDT", False), ("USDCE", USDCE, "DAI_USDCE", False)]),
        ("LINK", LINK, "WETH_LINK", False, [("USDC", USDC, "USDC_LINK", True), ("USDT", USDT, "LINK_USDT", False), ("USDCE", USDCE, "USDCE_LINK", False)]),
        ("UNI", UNI, "WETH_UNI", False, [("USDC", USDC, "USDC_UNI", True), ("USDT", USDT, "UNI_USDT", False), ("USDCE", USDCE, "USDCE_UNI", False)]),
        ("AAVE", AAVE, "WETH_AAVE", False, [("USDC", USDC, "USDC_AAVE", True), ("USDT", USDT, "AAVE_USDT", False), ("USDCE", USDCE, "USDCE_AAVE", False)]),
        ("PENDLE", PENDLE, "PENDLE_WETH", True, [("USDC", USDC, "PENDLE_USDC", False), ("USDT", USDT, "USDT_PENDLE", False), ("USDCE", USDCE, "USDCE_PENDLE", False)]),
        ("WSTETH", WSTETH, "WSTETH_WETH", True, [("USDC", USDC, "WSTETH_USDC", False), ("USDT", USDT, "USDT_WSTETH", False), ("USDCE", USDCE, "USDCE_WSTETH", False)]),
        ("LUSD", LUSD, "WETH_LUSD", False, [("USDC", USDC, "LUSD_USDC", False), ("USDT", USDT, "USDT_LUSD", False), ("USDCE", USDCE, "USDCE_LUSD", False)]),
    ]
    weth_stable_map = {"USDC": ("WETH_USDC", USDC), "USDT": ("WETH_USDT", USDT), "USDCE": ("WETH_USDCE", USDCE)}
    for alt_sym, alt_addr, weth_alt_key, alt_is_t0_in_weth, stable_specs in tri_legs:
        w_alt_pools = by_pair.get(weth_alt_key, [])
        if not w_alt_pools:
            continue
        for st_sym, st_addr, alt_st_key, st_is_t0_in_alt in stable_specs:
            w_st_key, _ = weth_stable_map[st_sym]
            w_st_pools = by_pair.get(w_st_key, [])
            alt_st_pools = by_pair.get(alt_st_key, [])
            if not w_st_pools or not alt_st_pools:
                continue
            for p_ws in w_st_pools[:3]:
                for p_as in alt_st_pools[:3]:
                    for p_wa in w_alt_pools[:3]:
                        # Price of WETH in STABLE (STABLE per 1 WETH)
                        px_weth_in_st = p_ws["price"]
                        # Price of ALT in STABLE (STABLE per 1 ALT)
                        px_alt_in_st = (1.0 / p_as["price"]) if st_is_t0_in_alt else p_as["price"]
                        # Price of ALT in WETH (WETH per 1 ALT)
                        px_alt_in_weth = p_wa["price"] if alt_is_t0_in_weth else (1.0 / p_wa["price"])
                        if px_weth_in_st <= 0 or px_alt_in_st <= 0 or px_alt_in_weth <= 0:
                            continue
                        weth_res_ws = float(p_ws.get("r0", 0.0))
                        weth_res_wa = float(p_wa.get("r1", 0.0) if alt_is_t0_in_weth else p_wa.get("r0", 0.0))
                        st_res_as = float(p_as.get("r0", 0.0) if st_is_t0_in_alt else p_as.get("r1", 0.0))
                        bottleneck_weth_res = min(weth_res_ws, weth_res_wa, st_res_as / max(500.0, univ3_eth_spot))
                        if bottleneck_weth_res < 0.04:
                            continue
                        fee_tot_bps = p_ws["fee_bps"] + p_as["fee_bps"] + p_wa["fee_bps"]
                        # Direction A: WETH -> STABLE -> ALT -> WETH
                        gross_ret_a = (px_weth_in_st / px_alt_in_st) * px_alt_in_weth
                        net_edge_a_bps = (gross_ret_a - 1.0) * 10000.0 - fee_tot_bps
                        # Direction B: WETH -> ALT -> STABLE -> WETH
                        gross_ret_b = (1.0 / px_alt_in_weth) * (px_alt_in_st / px_weth_in_st)
                        net_edge_b_bps = (gross_ret_b - 1.0) * 10000.0 - fee_tot_bps
                        for dir_lbl, net_eb, t_tok, m_tok, f1, f2 in (
                            (f"TRI_WETH_{st_sym}_{alt_sym}", net_edge_a_bps, st_addr, alt_addr, int(p_ws["fee_bps"] * 100), int(p_as["fee_bps"] * 100)),
                            (f"TRI_WETH_{alt_sym}_{st_sym}", net_edge_b_bps, alt_addr, st_addr, int(p_wa["fee_bps"] * 100), int(p_as["fee_bps"] * 100)),
                        ):
                            if -15.0 <= net_eb <= 250.0:
                                d_star_tri_weth = max(0.002, min(0.50, 0.35 * max(2.0, net_eb) * 1e-4 * bottleneck_weth_res))
                                d_star_tri_wei = int(d_star_tri_weth * 1e18)
                                triangular_cycles.append({
                                    "label": dir_lbl,
                                    "borrow_token": WETH,
                                    "target_token": t_tok,
                                    "mid_token": m_tok,
                                    "fee1": f1 if f1 in (100, 500, 3000, 10000) else 500,
                                    "fee2": f2 if f2 in (100, 500, 3000, 10000) else 500,
                                    "d_star_raw": d_star_tri_wei,
                                    "bottleneck_weth_res": round(bottleneck_weth_res, 4),
                                    "net_edge_bps": round(net_eb, 3),
                                    "fee_total_bps": round(fee_tot_bps, 2),
                                    "pool_1": p_ws["pool"],
                                    "pool_2": p_as["pool"],
                                    "pool_3": p_wa["pool"],
                                })
    triangular_cycles.sort(key=lambda x: (-x["net_edge_bps"], -x.get("bottleneck_weth_res", 0.0)))
    dedup_tri_cycles = []
    seen_tri_keys = set()
    for tc in triangular_cycles:
        tk = (tc["target_token"].lower(), tc["mid_token"].lower(), tc["fee1"], tc["fee2"])
        if tk not in seen_tri_keys:
            seen_tri_keys.add(tk)
            dedup_tri_cycles.append(tc)

    solved_probes.sort(
        key=lambda x: (
            -int(x["live_edge_bps"] > 0),
            -int(x["live_edge_bps"] > 0 and x["borrow_token"].lower() in (WETH.lower(), USDC.lower())),
            -x["est_gross_wei"],
            -x["live_edge_bps"],
        )
    )
    # Take up to 10 top depth-weighted routes per WETH/USDC pair (and up to 4 per other pair, up to 160 candidates) for parallel JSON-RPC batch verification
    seen_pair_cnt = {}
    eval_cands = []
    for p in solved_probes:
        pk = "_".join(p["label"].split("_")[1:3])
        is_w_p = p["borrow_token"].lower() in (WETH.lower(), USDC.lower())
        max_per_p = 10 if is_w_p else 4
        if seen_pair_cnt.get(pk, 0) < max_per_p and len(eval_cands) < 160:
            seen_pair_cnt[pk] = seen_pair_cnt.get(pk, 0) + 1
            eval_cands.append(p)

    # Direct Zero-StateOverride Multicall3 Simulation against deployed 0x690ff36ae25e1cf2441edaf061b750ff2701b5a7!
    def _sim_mc3_disjoint_slice(subcalls, rpc_idx):
        if not subcalls:
            return [(False, b"")] * len(subcalls)
        cd = encode_agg3(subcalls)
        payload = {
            "jsonrpc": "2.0",
            "id": 1,
            "method": "eth_call",
            "params": [
                {"to": MC3, "data": cd},
                "latest",
            ],
        }
        for attempt in range(len(RPCS)):
            url = RPCS[(rpc_idx + attempt) % len(RPCS)]
            req = urllib.request.Request(
                url,
                data=json.dumps(payload).encode(),
                headers={"Content-Type": "application/json", "User-Agent": "Mozilla/5.0"},
            )
            try:
                with urllib.request.urlopen(req, timeout=3.5) as resp:
                    parsed = json.loads(resp.read().decode())
                    if isinstance(parsed, dict) and parsed.get("result"):
                        return decode_agg3(parsed["result"], len(subcalls))
            except Exception:
                continue
        return [(False, b"")] * len(subcalls)

    # Stage 1: Partition eval_cands into pool-disjoint Multicall3 slices (max 24 per slice) across (0.50x, 1.00x, 2.25x) base d*
    for p in eval_cands:
        p["base_d_star_raw"] = p["d_star_raw"]
    sim_tasks = []
    for mult in (0.50, 1.00, 2.25):
        buckets = []  # list of (subcalls, meta_list, used_pools_set)
        lim_cands = 72 if mult in (0.50, 1.00) else 48
        for p in eval_cands[:lim_cands]:
            amt_test = max(1, int(p["base_d_star_raw"] * mult))
            cd = encode_fs(p["pool_borrow"], p["pool_sell"], p["borrow_token"], p["target_token"], amt_test, 1, p["zero_for_one_borrow"], p["zero_for_one_sell"], 0)
            pb_l, ps_l = p["pool_borrow"].lower(), p["pool_sell"].lower()
            placed = False
            for b_sc, b_meta, b_pools in buckets:
                if len(b_sc) < 24 and pb_l not in b_pools and ps_l not in b_pools:
                    b_sc.append((CONTRACT_ADDR, cd))
                    b_meta.append((p, amt_test))
                    b_pools.add(pb_l)
                    b_pools.add(ps_l)
                    placed = True
                    break
            if not placed:
                buckets.append(([(CONTRACT_ADDR, cd)], [(p, amt_test)], {pb_l, ps_l}))
        for b_sc, b_meta, _ in buckets:
            sim_tasks.append((b_sc, b_meta, len(sim_tasks)))

    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as ex:
        futs = [ex.submit(_sim_mc3_disjoint_slice, sc, h) for sc, _, h in sim_tasks]
        for fut, (_, meta_list, _) in zip(futs, sim_tasks):
            res_list = fut.result()
            for (ok_c, b_c), (p_ref, amt_used) in zip(res_list, meta_list):
                if ok_c and len(b_c) >= 32:
                    raw_prof = int.from_bytes(b_c[0:32], "big")
                    if raw_prof > 0:
                        bt_l = p_ref["borrow_token"].lower()
                        if bt_l == WETH.lower():
                            eq_wei = raw_prof
                        else:
                            t_usd = tok_usd_map.get(bt_l, 0.55)
                            eq_wei = int((raw_prof / (10 ** p_ref["borrow_dec"])) * (t_usd / max(500.0, univ3_eth_spot)) * 1e18)
                        if eq_wei > p_ref.get("live_verified_gross_wei", 0):
                            p_ref["live_verified_gross_wei"] = eq_wei
                            p_ref["d_star_raw"] = amt_used
                            p_ref["d_star_tiers_raw"] = [max(1, int(amt_used * 0.50)), amt_used, int(amt_used * 2.50), int(amt_used * 6.00)]

    # Stage 2 (Fine-Grained Sweet-Spot & Surge Backrun Refinement): Test (0.80x, 1.45x, 3.50x, 6.00x) around Stage-1 winning d_star_raw on top verified positive pairs
    pos_stage1 = [p for p in eval_cands if p.get("live_verified_gross_wei", 0) > 0]
    pos_stage1.sort(key=lambda x: (-int(x["borrow_token"].lower() in (WETH.lower(), USDC.lower())), -int(x.get("live_verified_gross_wei", 0))))
    for p in pos_stage1:
        p["stage1_best_raw"] = p["d_star_raw"]
    fine_tasks = []
    for fine_mult in (0.80, 1.45, 3.50, 6.00):
        f_buckets = []
        for p in pos_stage1[:24]:
            amt_fine = max(1, int(p["stage1_best_raw"] * fine_mult))
            cd_f = encode_fs(p["pool_borrow"], p["pool_sell"], p["borrow_token"], p["target_token"], amt_fine, 1, p["zero_for_one_borrow"], p["zero_for_one_sell"], 0)
            pb_l, ps_l = p["pool_borrow"].lower(), p["pool_sell"].lower()
            placed = False
            for b_sc, b_meta, b_pools in f_buckets:
                if len(b_sc) < 20 and pb_l not in b_pools and ps_l not in b_pools:
                    b_sc.append((CONTRACT_ADDR, cd_f))
                    b_meta.append((p, amt_fine))
                    b_pools.add(pb_l)
                    b_pools.add(ps_l)
                    placed = True
                    break
            if not placed:
                f_buckets.append(([(CONTRACT_ADDR, cd_f)], [(p, amt_fine)], {pb_l, ps_l}))
        for b_sc, b_meta, _ in f_buckets:
            fine_tasks.append((b_sc, b_meta, len(fine_tasks)))
    if fine_tasks:
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as ex:
            futs_f = [ex.submit(_sim_mc3_disjoint_slice, sc, h) for sc, _, h in fine_tasks]
            for fut_f, (_, meta_list, _) in zip(futs_f, fine_tasks):
                res_list = fut_f.result()
                for (ok_c, b_c), (p_ref, amt_used) in zip(res_list, meta_list):
                    if ok_c and len(b_c) >= 32:
                        raw_prof = int.from_bytes(b_c[0:32], "big")
                        if raw_prof > 0:
                            bt_l = p_ref["borrow_token"].lower()
                            if bt_l == WETH.lower():
                                eq_wei = raw_prof
                            else:
                                t_usd = tok_usd_map.get(bt_l, 0.55)
                                eq_wei = int((raw_prof / (10 ** p_ref["borrow_dec"])) * (t_usd / max(500.0, univ3_eth_spot)) * 1e18)
                            if eq_wei > p_ref.get("live_verified_gross_wei", 0):
                                p_ref["live_verified_gross_wei"] = eq_wei
                                p_ref["d_star_raw"] = amt_used
                                p_ref["d_star_tiers_raw"] = [max(1, int(amt_used * 0.50)), amt_used, int(amt_used * 2.50), int(amt_used * 6.00)]

    eval_cands.sort(
        key=lambda x: (
            -int(x.get("live_verified_gross_wei", 0) > 0),
            -int(x.get("live_verified_gross_wei", 0) > 0 and x["borrow_token"].lower() in (WETH.lower(), USDC.lower())),
            -int(x.get("live_verified_gross_wei", 0)),
            -int(bool(x.get("is_fixed_fee_low_gas")) and x["live_edge_bps"] > -5.0),
            -x["live_edge_bps"],
        )
    )

    # Zero-Waste Pool-Diversified WETH/USDC-First Pairs: Pass 1 selects up to 2 WETH/USDC routes per pool so top probes are maximally disjoint!
    multi_sized_probes = []
    seen_unique_pool_pairs = set()
    pool_usage_cnt = {}
    deferred_weth_probes = []
    deferred_other_probes = []
    for base_p in eval_cands:
        pb_l = base_p["pool_borrow"].lower()
        ps_l = base_p["pool_sell"].lower()
        upk = (pb_l, ps_l)
        if upk in seen_unique_pool_pairs:
            continue
        seen_unique_pool_pairs.add(upk)
        b_dec = int(base_p.get("borrow_dec", 18))
        bt_l = base_p["borrow_token"].lower()
        b_px = float(tok_usd_map.get(bt_l, univ3_eth_spot if bt_l == WETH.lower() else 1.0))
        loan_hum = float(base_p["d_star_raw"]) / (10 ** b_dec)
        loan_usd = round(loan_hum * b_px, 4)
        loan_inr = round(loan_usd * 94.92, 2)
        eq_w = int(base_p.get("live_verified_gross_wei", 0))
        gross_usd = round((eq_w / 1e18) * univ3_eth_spot, 6)
        gross_inr = round(gross_usd * 94.92, 4)
        single_gas_inr = round((206000 * 20_000_000 / 1e18) * univ3_eth_spot * 94.92, 4)
        base_clean = {k: v for k, v in base_p.items() if k != "borrow_dec"}
        base_clean["sizing_tier"] = "exact_peak_d_star"
        base_clean["pair_name"] = "_".join(base_p["label"].split("_")[1:3])
        base_clean["loan_amount_usd"] = loan_usd
        base_clean["loan_amount_inr"] = loan_inr
        base_clean["live_verified_gross_usd"] = gross_usd
        base_clean["live_verified_gross_inr"] = gross_inr
        base_clean["est_single_gas_inr"] = single_gas_inr
        base_clean["net_if_solo_inr"] = round(gross_inr - single_gas_inr, 4)
        is_weth_or_usdc = bt_l in (WETH.lower(), USDC.lower())
        if is_weth_or_usdc and eq_w > 0:
            if pool_usage_cnt.get(pb_l, 0) < 2 and pool_usage_cnt.get(ps_l, 0) < 2:
                pool_usage_cnt[pb_l] = pool_usage_cnt.get(pb_l, 0) + 1
                pool_usage_cnt[ps_l] = pool_usage_cnt.get(ps_l, 0) + 1
                multi_sized_probes.append(base_clean)
            else:
                deferred_weth_probes.append(base_clean)
        else:
            deferred_other_probes.append(base_clean)
        if len(multi_sized_probes) >= 60:
            break
    for dp in deferred_weth_probes + deferred_other_probes:
        if len(multi_sized_probes) >= 60:
            break
        multi_sized_probes.append(dp)

    # Compute exact live Disjoint Multi-Route Bundle Summary across all non-overlapping positive WETH routes
    disjoint_bundle_legs = []
    disjoint_used_pools = {"0x6f38e884725a116c9c7fbf208e79fe8828a2595f"}
    for mp in multi_sized_probes:
        if int(mp.get("live_verified_gross_wei", 0)) > 0 and mp["borrow_token"].lower() == WETH.lower():
            pb_m, ps_m = mp["pool_borrow"].lower(), mp["pool_sell"].lower()
            if pb_m not in disjoint_used_pools and ps_m not in disjoint_used_pools:
                disjoint_used_pools.add(pb_m)
                disjoint_used_pools.add(ps_m)
                disjoint_bundle_legs.append(mp)
    tot_disj_wei = sum(int(x["live_verified_gross_wei"]) for x in disjoint_bundle_legs)
    tot_disj_inr = round((tot_disj_wei / 1e18) * univ3_eth_spot * 94.92, 4)
    top4_disj_wei = sum(int(x["live_verified_gross_wei"]) for x in disjoint_bundle_legs[:4])
    top4_disj_inr = round((top4_disj_wei / 1e18) * univ3_eth_spot * 94.92, 4)
    disjoint_bundle_summary = {
        "disjoint_positive_legs_count": len(disjoint_bundle_legs),
        "total_disjoint_gross_wei": tot_disj_wei,
        "total_disjoint_gross_inr": tot_disj_inr,
        "top4_bundle_gross_wei": top4_disj_wei,
        "top4_bundle_gross_inr": top4_disj_inr,
        "top4_bundle_labels": [x["label"] for x in disjoint_bundle_legs[:4]],
    }

    verified_pos_count = sum(1 for x in eval_cands if x.get("live_verified_gross_wei", 0) > 0)
    fixed_v3_count = sum(1 for x in solved_probes if x.get("is_fixed_fee_low_gas"))
    pos_tri_count = sum(1 for x in triangular_cycles if x.get("net_edge_bps", -99.0) > 0.0)
    doc = {
        "ts": time.time(),
        "scan_ms": round((time.time() - t0_start) * 1000.0, 2),
        "univ3_1bp_eth_spot_usd": round(univ3_eth_spot, 2),
        "pools_indexed": len(POOLS),
        "competing_pairs_indexed": len(by_pair),
        "solved_dstar_pairs": len(solved_probes),
        "fixed_fee_low_gas_pairs": fixed_v3_count,
        "verified_positive_pairs_now": verified_pos_count,
        "triangular_cycles_solved": len(triangular_cycles),
        "positive_triangular_cycles_now": pos_tri_count,
        "multi_sizing_tiers": ["0.50x_d_star", "0.82x_d_star", "1.00x_d_star", "1.18x_d_star", "1.75x_d_star"],
        "disjoint_bundle_summary": disjoint_bundle_summary,
        "top_triangular_cycles": dedup_tri_cycles[:20],
        "top_probes": multi_sized_probes[:60],
    }
    out_txt = json.dumps(doc, indent=2)
    if (len(by_pair) >= 18 and len(multi_sized_probes) >= 30 and verified_pos_count >= 12) or (not OUT_FILE.exists()):
        tmp_out = OUT_FILE.with_suffix(".json.tmp")
        tmp_out.write_text(out_txt)
        tmp_out.replace(OUT_FILE)
        try:
            docs_out = BASE_DIR / "docs" / "reports" / OUT_FILE.name
            if docs_out.parent.exists():
                d_tmp = docs_out.with_suffix(".json.tmp")
                d_tmp.write_text(out_txt)
                d_tmp.replace(docs_out)
        except Exception:
            pass
    if not quiet:
        print(json.dumps({k: v for k, v in doc.items() if k not in ("top_probes", "top_triangular_cycles")}))
    return 0


if __name__ == "__main__":
    sys.exit(main())
